mapper.update:
update document
title=#{title}, status=#{status}, audit_status=#{auditStatus}, visibility=#{visibility}, author_id=#{authorId}, category_id=#{categoryId}, team_id=#{teamId}, view_count=#{viewCount}, like_count=#{likeCount}, reject_reason=#{rejectReason}, updated_at=#{updatedAt},
where id=#{id}

mapper.select:
select d.id, d.title, d.version, d.status, d.visibility, d.author_id, d.category_id, d.view_count, d.like_count, d.favorite_count, d.created_at, d.updated_at from document d left join document_tag dt on d.id = dt.document_id
and d.status=#{status} and d.category_id=#{categoryId} and d.created_at >= #{startTime} and d.created_at <= #{endTime}
and dt.tag_id in
#{tagId}
and d.visibility = 2
and d.visibility = 1
and d.team_id=#{teamId}
and d.visibility = 0 and (d.author_id = #{authorId})
and ( d.visibility = 2
or (d.visibility = 1 and d.team_id = #{teamId})
or (d.visibility = 0 and d.author_id = #{authorId})
)
GROUP BY d.id order by d.updated_at desc
